import sys
sys.path.insert(0,"/Users/spaceman/Desktop/FrontierMath Open Problems/arithmetic-kakeya/src")
import fastcore, fastcore_rs
PY_F,RS_F=fastcore._force_py,fastcore_rs.force
PY_R,RS_R=fastcore._rank_py,fastcore_rs.rank
def go(tag, fn, *a, **k):
    fastcore._INV.clear()
    try: r = fn(*a,**k)
    except BaseException as e: r = (type(e).__name__, str(e)[:70])
    print("%-34s %s" % (tag, r))
go("n=2**70  rs", RS_F, [[1,-1,0,0]], 1<<70, set())
print("%-34s %s" % ("n=2**70  py", "(not run: Python allocates U = list(range(2**70)) and never returns)"))
go("p=2**70  py", PY_R, [[1,0],[0,1]], 1<<70)
go("p=2**70  rs", RS_R, [[1,0],[0,1]], 1<<70)
go("p kwarg  py", PY_R, [[1,0],[0,1]], p=7)
go("p kwarg  rs", RS_R, [[1,0],[0,1]], p=7)
go("force p kwarg py", PY_F, [[1,1,0,0],[0,0,1,1]], 2, set(), p=2)
go("force p kwarg rs", RS_F, [[1,1,0,0],[0,0,1,1]], 2, set(), p=2)
go("force T0 kwarg py", PY_F, [[1,-1]], 1, T0=set())
go("force T0 kwarg rs", RS_F, [[1,-1]], 1, T0=set())
go("rows=dict py", PY_F, {(1,-1,0,0):1,(0,0,1,-1):1}, 2, set())
go("rows=dict rs", RS_F, {(1,-1,0,0):1,(0,0,1,-1):1}, 2, set())
go("rank rows=dict py", PY_R, {(1,0):1,(0,1):1})
go("rank rows=dict rs", RS_R, {(1,0):1,(0,1):1})
go("rank rows=str py", PY_R, "ab")
go("rank rows=str rs", RS_R, "ab")
go("n=float py", PY_F, [[1,-1]], 1.0, set())
go("n=float rs", RS_F, [[1,-1]], 1.0, set())
go("n=2**63 py-skip", lambda: None)
go("n=2**63 rs", RS_F, [[1,-1]], 1<<63, set())
go("p=bool True py", PY_R, [[1,0],[0,1]], True)
go("p=bool True rs", RS_R, [[1,0],[0,1]], True)
go("rank rows=range py", PY_R, range(3))
go("rank rows=range rs", RS_R, range(3))
go("rank empty gen expr py", PY_R, (x for x in []))
go("rank empty gen expr rs", RS_R, (x for x in []))
go("rank rows=[] tuple-of-0 py", PY_R, [()])
go("rank rows=[] tuple-of-0 rs", RS_R, [()])
go("force rows=set py", PY_F, {(1,-1,0,0),(0,0,1,-1)}, 2, set())
go("force rows=set rs", RS_F, {(1,-1,0,0),(0,0,1,-1)}, 2, set())
